sys_ux_data_broker_transform.required_translations:
[ {
  "message" : "Table",
  "comment" : ""
}, {
  "message" : "Table to look up",
  "comment" : ""
}, {
  "message" : "View",
  "comment" : ""
}, {
  "message" : "view to look up",
  "comment" : ""
} ]

sys_ux_data_broker_transform.script:
function transform(input) {
    var results = [];

    if (!input.table) {
        return results;
    }

    // Query sys_ui_element for fields in the given view
    var grUiElement = new GlideRecord('sys_ui_element');
    grUiElement.addQuery('name', input.table); // Query for the specific table
    if (input.view) { // Check for the view name
        grUiElement.addQuery('view', input.view);
    }
    grUiElement.query();

    var visibleFields = [];
    while (grUiElement.next()) {
        visibleFields.push(grUiElement.getValue('element')); // Get field names
    }

    // Query sys_dictionary for field details
    var grSysDict = new GlideRecord('sys_dictionary');
    grSysDict.addEncodedQuery('name=' + input.table + '^internal_type!=collection^internal_typeISNOTEMPTY');
    grSysDict.query();

    while (grSysDict.next()) {
        var fieldName = grSysDict.getValue("element");

        // Skip fields not in the specified view, if provided
        if (input.view && !visibleFields.includes(fieldName)) {
            continue;
        }

        results.push({
            column_label: grSysDict.getValue("column_label"), // Field label
            element: fieldName,                              // Field name
            type: grSysDict.getValue("internal_type"),       // Field type (e.g., string, integer)
            reference: grSysDict.getValue("reference"),      // Reference table (if applicable)
            display: grSysDict.getValue("display"),          // Display flag (true/false)
        });
    }

    return results;
}
